<script setup lang="ts">
import { nextTick, ref } from 'vue'
import MarkdownIt from 'markdown-it'
import AppShell from '../components/product/AppShell.vue'
import AiCreating from '../components/product/AiCreating.vue'
import http from '../utils/http'
const question = ref(''); const answer = ref(''); const loading = ref(false); const tab = ref<'text'|'diagram'|'video'>('text'); const error = ref('')
const md = new MarkdownIt({ html: false, breaks: true }); const suggestions = ['Python 变量为什么不需要声明类型？','for 循环和 while 循环怎么选？','用图解释函数调用过程']
async function renderDiagram() { await nextTick(); const target = document.querySelector('#tutor-diagram'); if (!target) return; try { const mermaid = (await import('mermaid')).default; mermaid.initialize({ startOnLoad: false, theme: document.documentElement.classList.contains('dark') ? 'dark' : 'neutral' }); const source = `flowchart LR\n A[提出问题] --> B[检索知识]\n B --> C[拆解原理]\n C --> D[示例与练习]`; const result = await mermaid.render(`diagram-${Date.now()}`, source); target.innerHTML = result.svg } catch { target.textContent = '图解暂时无法渲染，请查看文字答案。' } }
async function ask(text = question.value) { if (!text.trim()) return; question.value = text; loading.value = true; error.value = ''; answer.value = ''; try { const response = await http.post('/api/chat/send', { message: text, course: 'Python' }, { timeout: 60000 }); answer.value = response.data.reply || '已完成分析'; await renderDiagram() } catch (cause) { error.value = cause instanceof Error ? cause.message : '辅导服务暂时不可用' } finally { loading.value = false } }
</script>
<template><AppShell><section class="tutor-layout"><aside class="tutor-prompt atmosphere-soft"><span class="eyebrow">智能辅导 Agent</span><img src="/assets/mascot-chat.png" alt="耐心的小智析析" /><h1>哪里卡住了？<br />我们一起拆开看。</h1><form @submit.prevent="ask()"><textarea v-model="question" rows="5" maxlength="5000" placeholder="输入课程问题…" /><button class="primary-button" :disabled="!question.trim() || loading">开始讲解</button></form><div class="suggestion-list"><button v-for="item in suggestions" :key="item" @click="ask(item)">{{ item }}</button></div></aside><section class="tutor-answer"><div class="answer-tabs"><button :class="{ active: tab === 'text' }" @click="tab = 'text'">文字讲解</button><button :class="{ active: tab === 'diagram' }" @click="tab = 'diagram'; renderDiagram()">图解</button><button :class="{ active: tab === 'video' }" @click="tab = 'video'">视频预留</button></div><AiCreating v-if="loading" label="正在检索与组织讲解" /><div v-else-if="error" class="error-banner">{{ error }}</div><div v-else-if="!answer" class="answer-empty"><img src="/assets/mascot-thinking.png" alt="" loading="lazy" /><p>你的问题会在这里变成清晰的文字与图解。</p></div><article v-else-if="tab === 'text'" class="markdown-body" v-html="md.render(answer)" /><div v-show="answer && tab === 'diagram'" id="tutor-diagram" class="diagram-panel" /><div v-if="answer && tab === 'video'" class="video-placeholder"><img src="/assets/icon-video.svg" alt="" /><h2>视频讲解能力已预留</h2><p>当前版本先提供可验证的文字与图解，不返回虚假视频。</p></div></section></section></AppShell></template>
